 1→/**
 2→ * Splits a list into pages.
 3→ * page is 1-based: page 1 is the first `perPage` items.
 4→ */
 5→export function paginate(items, page, perPage = 10) {
 6→	if (!Array.isArray(items)) {
 7→		throw new TypeError("items must be an array");
 8→	}
 9→	if (perPage < 1) {
10→		throw new RangeError("perPage must be at least 1");
11→	}
12→	const start = page * perPage;
13→	const end = start + perPage;
14→	return {
15→		items: items.slice(start, end),
16→		page,
17→		totalPages: Math.floor(items.length / perPage),
18→	};
19→}
20→
21→export function pageNumbers(totalPages) {
22→	const pages = [];
23→	for (let i = 1; i <= totalPages; i++) {
24→		pages.push(i);
25→	}
26→	return pages;
27→}

